  `trfr_adv_prod_code` varchar(30) COMMENT '转垫款产品号',
  `adv_due_bill_num` varchar(32) COMMENT '垫款借据编号',
  `trfr_adv_amt` decimal(21,2) DEFAULT 0.00 COMMENT '转垫款金额',
  `cntpr_bank_class` varchar(2) COMMENT '对手行类别代码(00-中央银行,01-国有商业银行,02-政策性银行,03-城市商业银行,04-农村商业银行,...)',
  `cntpr_bank_num` varchar(12) COMMENT '对方行号',
  `cntpr_bank_nm` varchar(300) COMMENT '对方行名',
  `bill_catg` varchar(1) NOT NULL COMMENT '票据种类代码(1-纸质银行承兑汇票,2-电子银行承兑汇票,3-纸质商业承兑汇票,4-电子商业承兑汇票)',
  `bill_num` varchar(60) NOT NULL COMMENT '票据号码',
  `dsct_sub_bill_rng_strt_num` varchar(60) COMMENT '子票区间起始号码',
  `dsct_sub_bill_rng_end_num` varchar(60) COMMENT '子票区间终止号码',
  `par_amt` decimal(21,2) DEFAULT 0.00 COMMENT '票面金额',
  `bill_issue_dt` varchar(8) NOT NULL COMMENT '票据签发日期',
  `bank_bill_matu_dt` varchar(8) NOT NULL COMMENT '票据到期日期',
  `adjust_dys` int(10) DEFAULT 0 COMMENT '调整天数',
  `dawer_full_nm` varchar(40) COMMENT '出票人中文名称',
  `paye_full_nm` varchar(40) COMMENT '收款人中文名称',
  `acpt_bank_num` varchar(12) COMMENT '承兑行行号',
  `acpt_bank_nm` varchar(200) COMMENT '承兑行行名',
  `acpt_bank_catg` varchar(1) COMMENT '承兑行种类代码(1-本行,2-他行)',
  `dsct_ste` varchar(1) NOT NULL COMMENT '贴现状态代码(1-正常,2-锁定,3-结清)'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC collate=utf8mb4_unicode_ci COMMENT='贴现票据信息主表';

