  `need_incrs_dec_int` decimal(21,7) DEFAULT 0 NOT NULL COMMENT '应加/减利息',
  `need_incrs_dec_acmlv_num` decimal(21,2) DEFAULT 0 NOT NULL COMMENT '应加/减积数',
  `acmlv_num_within_last_prd` decimal(21,2) DEFAULT 0 NOT NULL COMMENT '上期内积数',
  `last_dy_acrl_tax_rate` decimal(12,7) DEFAULT 0 NOT NULL COMMENT '上日计提税率',
  `paybl_revnu` decimal(21,2) DEFAULT 0 NOT NULL COMMENT '应缴税金',
  `last_dy_acrl_revnu` decimal(21,7) DEFAULT 0 NOT NULL COMMENT '上日计提税金',
  `last_int_pymt_dt` varchar(8) NOT NULL COMMENT '上次付息日期',
  `last_int_caln_rule` varchar(2) COMMENT '上次计息规则代码(00-标准/标准(30/360),01-对月对日(30/365,366),02-标准/365(30/365),10-实际/标准(31/360),11-实际/实际(31/365,366),...)',
  `last_int_adjust_meth` varchar(1) COMMENT '上次利息调整方法代码(0-多段调整,1-积数调整,2-储蓄天数积数调整（仅用于移行数据）)',
  `last_int_oprn` varchar(10) COMMENT '上次利息操作代码(ACCRUAL-利息计提,ADJUSTMENT-调整利息,POSTING-支付利息,REVIEW-利率更新)',
  `last_int_serl_num` bigint(32) DEFAULT 0 NOT NULL COMMENT '上次利息序号',
  `last_acrl_int_rate` decimal(12,7) DEFAULT 0 NOT NULL COMMENT '上次计提利率',
  `int_caln_dys` bigint(19) DEFAULT 0 NOT NULL COMMENT '计息天数',
  `last_prd_int_caln_dys` bigint(19) DEFAULT 0 NOT NULL COMMENT '上期计息天数',
  `this_yr_acmld_acmlv_num` decimal(21,2) DEFAULT 0 NOT NULL COMMENT '本年累计积数',
  `last_yr_acmld_acmlv_num` decimal(21,2) DEFAULT 0 NOT NULL COMMENT '上年累计积数',
  `last_int_stlmt_dt` varchar(8) COMMENT '上次结息日',
  `next_int_stlmt_dt` varchar(8) COMMENT '下次结息日期',
  `acrl_pstg_freq` varchar(8) COMMENT '计提入账频率',
  `next_acrl_pstg_dt` varchar(8) COMMENT '下次计提入账日期',
  `tax_caln_rate` decimal(8,6) DEFAULT 0 NOT NULL COMMENT '计税税率',
  `btch_grp_num` varchar(60) NOT NULL COMMENT '批量分组号',
  `wthr_simp_int_caln` varchar(1) COMMENT '简单计息标志(Y-是,N-否)',
  `alrdy_pay_int` decimal(21,7) DEFAULT 0 NOT NULL COMMENT '已付利息'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC collate=utf8mb4_unicode_ci COMMENT='账户计息定义表';

