create table `kdpa_acct_int_rate` (
  `lgl_pern_code` varchar(4) NOT NULL COMMENT '法人代码',
  `mntnc_org` varchar(12) NOT NULL COMMENT '维护机构号',
  `mntnc_tlr` varchar(8) NOT NULL COMMENT '维护柜员号',
  `mntnc_dt` varchar(8) NOT NULL COMMENT '维护日期',
  `mntnc_rung_num` varchar(32) NOT NULL COMMENT '维护流水号',
  `txn_code` varchar(20) NOT NULL COMMENT '核心交易码',
  `tmstp` bigint(19) DEFAULT 0 NOT NULL COMMENT '乐观锁时间戳',
  `rec_ste` varchar(1) NOT NULL COMMENT '记录状态代码(0-正常,1-删除)',
  `affr_ste` varchar(1) DEFAULT 'O' NOT NULL COMMENT '事务状态代码(O-正常,T-在途)',
  `glbl_affr_rung_num` varchar(60) COMMENT '全局事务流水号',
  `affr_ste_upd_num` varchar(40) COMMENT '事务状态更新唯一编号',
  `lblty_acct_num` varchar(40) NOT NULL COMMENT '负债账号',
  `ccy_code_num` varchar(3) COMMENT '币种(AUD-澳大利亚元,CAD-加元,CHF-瑞士法郎,DKK-丹麦克朗,EUR-欧元,...)',
  `lblty_int_rate_tp` varchar(8) NOT NULL COMMENT '负债利率类型代码(ZHENLXLV-正利息利率,DAOQLXLV-到期利息利率,FUFULXLV-负利息利率,WEIYEDLV-未使用额度利率,CHAOEDLV-超额利率,...)',
  `seq_num` bigint(32) DEFAULT 0 NOT NULL COMMENT '签约顺序号',
  `int_rate_code` varchar(20) COMMENT '利率编号',
  `int_rate_num_tp` varchar(1) COMMENT '利率编号类型代码(0-标准,1-LIBOR,2-HIBOR,3-SIBOR,4-SHIBOR,...)',
  `int_rate_amt_lv` decimal(21,2) DEFAULT 0 NOT NULL COMMENT '利率金额档次',
  `hier_int_rate_dept_prd` varchar(6) COMMENT '层次利率存期',
  `dept_prd` varchar(6) COMMENT '存期',
  `int_rate_dept_prd_flg` varchar(1) COMMENT '利率存期代码(0-产品约定存期,1-账户约定存期,2-实际存期,3-自定义存期)',
  `int_rate_bal_flg` varchar(1) COMMENT '利率余额代码(0-账户余额,1-平均余额,2-明细余额)',
  `int_rate_afld_lv_way` varchar(1) NOT NULL COMMENT '利率靠档方式代码(0-挂靠对应档，无对应档则报错。,1-挂靠较低档,2-挂靠较高档)',
  `int_rate_num_eff_dt` varchar(8) COMMENT '账户利率编号生效日',
  `int_rate_num_invld_dt` varchar(8) COMMENT '利率编号失效日',
  `int_rate_cfrm_dt` varchar(1) COMMENT '利率确定日期代码(0-开户日,1-结息日)',
  `open_acct_int_rate` decimal(12,7) DEFAULT 0 NOT NULL COMMENT '开户利率',
  `bchmk_int_rate` decimal(12,7) DEFAULT 0 NOT NULL COMMENT '基准利率',
  `exec_int_rate` decimal(12,7) DEFAULT 0 NOT NULL COMMENT '执行利率',
  `int_rate_last_upd_dt` varchar(8) NOT NULL COMMENT '利率上次更新日',
  `int_rate_next_upd_dt` varchar(8) COMMENT '利率下次更新日',
  `last_acrl_int_rate` decimal(12,7) DEFAULT 0 NOT NULL COMMENT '上次计提利率',
  `int_rate_change_adjust_int_flg` varchar(1) NOT NULL COMMENT '利率变化调整利息代码(0-不调整利息,1-调整利息)',
  `adjust_int_rate_flg` varchar(1) NOT NULL COMMENT '利率变化调整利率代码(0-不调整利率,1-调整利率,2-利率上升调整,3-利率下降调整)',
  `adjust_pref_flg` varchar(1) COMMENT '优惠变化调整优惠代码(0-不调整,1-调整,2-优惠上升调整,3-优惠下降调整)',
  `pref_last_upd_dt` varchar(8) COMMENT '优惠上次更新日',
  `pref_next_upd_dt` varchar(8) COMMENT '优惠下次更新日',
  `layer_tp` varchar(1) COMMENT '利率分层类型代码(1-按存期,2-按金额)',
  `int_rate_upd_deal_way` varchar(1) COMMENT '利率更新处理方式代码(0-每日主动更新,1-被动更新)',
  `int_rate_pref_invld_dt` varchar(8) COMMENT '利率优惠失效日期'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC collate=utf8mb4_unicode_ci COMMENT='账户利率定义表';

