  `prcpl_trfr_in_lblty_acct_num` varchar(40) COMMENT '本金转入负债账号',
  `int_trfr_in_cust_acct_num` varchar(40) COMMENT '利息转入客户账号',
  `int_trfr_in_lblty_acct_num` varchar(40) COMMENT '利息转入负债账号',
  `ctrct_ste_code` varchar(1) NOT NULL COMMENT '合约状态代码(1-已签约,2-已解约)'
