  `serl_num_long` bigint(32) DEFAULT 0 NOT NULL COMMENT '长序号',
  `int_grp_num` bigint(32) DEFAULT 0 NOT NULL COMMENT '利息组号',
  `int_grp_qty` bigint(19) DEFAULT 0 NOT NULL COMMENT '利息组数量',
  `int_tp` varchar(8) NOT NULL COMMENT '利息类型代码(ZHENGGLX-正利息,DAOQIILX-到期利息,FUFUFULX-负利息,WEIYEDLX-未使用额度利息,CHAOEDLX-超额利息,...)',
  `int_oprn_code` varchar(10) NOT NULL COMMENT '利息操作代码(ACCRUAL-利息计提,ADJUSTMENT-调整利息,POSTING-支付利息,REVIEW-利率更新)',
  `int_caln_strt_dt` varchar(8) NOT NULL COMMENT '计息起始日期',
  `int_caln_end_dt` varchar(8) NOT NULL COMMENT '计息终止日期',
  `bchmk_acrl_int_rate_num` varchar(20) COMMENT '基准计提利率编号',
  `int_rate_amt_lv` decimal(21,2) DEFAULT 0 NOT NULL COMMENT '利率金额档次',
  `hier_int_rate_dept_prd` varchar(6) COMMENT '层次利率存期',
  `int_rate_afld_lv_way` varchar(1) COMMENT '利率靠档方式代码(0-挂靠对应档，无对应档则报错。,1-挂靠较低档,2-挂靠较高档)',
  `acct_bchmk_int_rate` decimal(12,7) DEFAULT 0 COMMENT '账户基准利率',
  `exec_int_rate` decimal(12,7) DEFAULT 0 NOT NULL COMMENT '执行利率',
  `int_rate_eff_dt` varchar(8) DEFAULT '0' COMMENT '利率生效日期',
  `acrl_tax_rate` decimal(8,6) DEFAULT 0 NOT NULL COMMENT '计提税率',
  `actl_int_occr_amt` decimal(21,7) DEFAULT 0 NOT NULL COMMENT '实际利息发生额',
  `int_tax_occr_amt` decimal(21,7) DEFAULT 0 NOT NULL COMMENT '利息税发生额',
  `bchmk_int_occr_amt` decimal(21,7) DEFAULT 0 COMMENT '基准利息发生额',
  `int_aft_adjust` decimal(21,7) DEFAULT 0 COMMENT '调整后利息',
  `int_tax_aft_adjust` decimal(21,7) DEFAULT 0 COMMENT '调整后利息税',
  `layer_int_rate_flg` varchar(1) COMMENT '分层利率代码(0-单层,1-多层)',
  `lv_int_caln_amt` decimal(21,2) DEFAULT 0 COMMENT '档次计息金额',
  `lv_int_caln_dept_prd` varchar(6) COMMENT '档次计息存期',
  `totl_int_caln_bal` decimal(21,2) DEFAULT 0 COMMENT '总计息余额',
  `acmlv_num` decimal(21,2) DEFAULT 0 COMMENT '积数',
  `std_int_caln_meth` varchar(2) COMMENT '标准计息方法代码(00-标准/标准(30/360),01-对月对日(30/365,366),02-标准/365(30/365),10-实际/标准(31/360),11-实际/实际(31/365,366),...)',
  `detl_use_flg` varchar(1) COMMENT '明细使用标志(Y-是,N-否)',
  `int_adjust_use_flg` varchar(1) COMMENT '调整使用代码(0-利息调整时不使用,1-利息调整时使用,2-该笔调整发生在上次结息日前,3-付息段不记会计账)',
  `int_adjust_meth` varchar(1) COMMENT '利息调整方法代码(0-多段调整,1-积数调整,2-储蓄天数积数调整（仅用于移行数据）)',
  `last_int_stlmt_dt` varchar(8) COMMENT '上次结息日',
  `int_rate_flt_flg` varchar(1) COMMENT '利率浮动标识代码(0-不浮动,1-按系统浮动,2-手工浮动)',
  `flt_val` decimal(12,7) DEFAULT 0 COMMENT '浮动值',
  `int_rate_pref_code` varchar(1) COMMENT '利率优惠代码(0-不优惠,1-按系统优惠,2-手工优惠)',
  `pref_val` decimal(12,7) DEFAULT 0 COMMENT '优惠值'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC collate=utf8mb4_unicode_ci COMMENT='账户利息明细表';

