  `acd_non_acd_ste` varchar(1) COMMENT '应计非应计状态(0-应计,1-非应计)',
  `asset_ste` varchar(1) DEFAULT '1' COMMENT '资产状态代码(1-正常,2-证券化)',
  `rdmpn_tm_pnt_int_clrd_flg` varchar(1) DEFAULT 'Y' COMMENT '赎回时点利息还清标志(Y-是,N-否)',
  `loan_form` varchar(1) COMMENT '贷款形态(0-正常,1-逾期,2-呆滞,3-呆账)',
  `loan_acct_ste` varchar(1) COMMENT '贷款账户状态(0-正常,1-销户,2-已核销,3-准销户)',
  `chk_write_off_ste` varchar(1) DEFAULT '0' COMMENT '核销状态代码(0-未核销,1-全部核销,2-部分核销)',
  `open_acct_dt` varchar(8) COMMENT '开户日期',
  `open_acct_org` varchar(12) COMMENT '开户机构号',
  `open_acct_tlr_num` varchar(8) COMMENT '开户柜员号',
  `open_acct_rung_num` varchar(32) COMMENT '开户流水号',
  `cncl_acct_dt` varchar(8) COMMENT '销户日期',
  `cncl_acct_tlr` varchar(8) COMMENT '销户柜员号',
  `cncl_acct_org` varchar(12) COMMENT '销户机构号',
  `cncl_acct_rung_num` varchar(32) COMMENT '销户流水号',
  `btch_grp_num` varchar(60) COMMENT '批量分组号',
  `chnl_code` varchar(7) COMMENT '渠道代码',
  `be_rvrsd_flg` varchar(1) COMMENT '被冲正代码(0-无关,1-被冲正,2-冲正,3-被隔日冲正,4-被回冲,...)'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC collate=utf8mb4_unicode_ci COMMENT='贷款账户主表';

