  `mntnc_org` varchar(12) NOT NULL COMMENT '维护机构号',
  `mntnc_tlr` varchar(8) NOT NULL COMMENT '维护柜员号',
  `mntnc_dt` varchar(8) NOT NULL COMMENT '维护日期',
  `mntnc_rung_num` varchar(32) NOT NULL COMMENT '维护流水号',
  `txn_code` varchar(20) NOT NULL COMMENT '核心交易码',
  `tmstp` bigint(19) DEFAULT 0 NOT NULL COMMENT '乐观锁时间戳',
  `rec_ste` varchar(1) NOT NULL COMMENT '记录状态代码(0-正常,1-删除)',
  `affr_ste` varchar(1) DEFAULT 'O' NOT NULL COMMENT '事务状态代码(O-正常,T-在途)',
  `glbl_affr_rung_num` varchar(60) COMMENT '全局事务流水号',
  `affr_ste_upd_num` varchar(40) COMMENT '事务状态更新唯一编号',
  `loan_due_bill_num` varchar(32) NOT NULL COMMENT '贷款借据号',
  `this_prd_prds` int(10) DEFAULT 0 NOT NULL COMMENT '本期期数',
  `this_prd_sub_prds` int(10) DEFAULT 1000 NOT NULL COMMENT '本期子期数',
  `bchmk_strt_dt` varchar(8) NOT NULL COMMENT '基准起始日',
  `bchmk_matu_dt` varchar(8) NOT NULL COMMENT '基准到期日',
  `strt_dt` varchar(8) NOT NULL COMMENT '起始日期',
  `matu_dt` varchar(8) NOT NULL COMMENT '到期日期',
  `grace_prd_matu_dt` varchar(8) NOT NULL COMMENT '宽限期到期日',
  `last_rpymt_dt` varchar(8) COMMENT '上次还款日',
  `next_rpymt_dt` varchar(8) COMMENT '下次还款日',
  `intl_prcpl` decimal(21,2) DEFAULT 0 COMMENT '初始本金',
  `intl_int` decimal(21,2) DEFAULT 0 COMMENT '初始利息',
  `instmt_prcpl` decimal(21,2) DEFAULT 0 COMMENT '期供本金',
  `rcvbl_acd_int` decimal(21,2) DEFAULT 0 COMMENT '应收应计利息',
  `urge_collt_acd_int` decimal(21,2) DEFAULT 0 COMMENT '催收应计利息',
  `rcvbl_db_int` decimal(21,2) DEFAULT 0 COMMENT '应收欠息',
  `urge_collt_db_int` decimal(21,2) DEFAULT 0 COMMENT '催收欠息',
  `rcvbl_acd_pnly_int` decimal(21,2) DEFAULT 0 COMMENT '应收应计罚息',
  `urge_collt_acd_pnly_int` decimal(21,2) DEFAULT 0 COMMENT '催收应计罚息',
  `rcvbl_pnly_int` decimal(21,2) DEFAULT 0 COMMENT '应收罚息',
  `urge_collt_pnly_int` decimal(21,2) DEFAULT 0 COMMENT '催收罚息',
  `acd_cmpd_int` decimal(21,2) DEFAULT 0 COMMENT '应计复息',
  `cmpd_int` decimal(21,2) DEFAULT 0 COMMENT '复息',
  `rcvbl_acd_output_tax` decimal(21,2) DEFAULT 0 COMMENT '应收应计销项税',
  `urge_collt_acd_output_tax` decimal(21,2) DEFAULT 0 COMMENT '催收应计销项税',
  `actl_acd_int` decimal(21,7) DEFAULT 0 COMMENT '实际应计利息',
  `actl_acd_pnly_int` decimal(21,7) DEFAULT 0 COMMENT '实际应计罚息',
  `actl_acd_cmpd_int` decimal(21,7) DEFAULT 0 COMMENT '实际应计复息',
  `acd_subsd_int` decimal(21,2) DEFAULT 0 COMMENT '应计贴息',
  `rcvbl_subsd_int` decimal(21,2) DEFAULT 0 COMMENT '应收贴息',
  `chk_write_off_int` decimal(21,2) DEFAULT 0.00 COMMENT '核销利息',
  `alrdy_chk_write_off_prcpl_int` decimal(21,2) DEFAULT 0.0 COMMENT '已核销本金利息',
  `actl_chk_write_off_prcpl_int` decimal(21,2) DEFAULT 0.0 COMMENT '实际核销本金利息',
  `this_prd_ste` varchar(1) COMMENT '本期状态(0-正常,1-逾期,2-呆滞,3-呆账,4-核销,...)',
  `acd_non_acd_ste` varchar(1) COMMENT '应计非应计状态(0-应计,1-非应计)',
  `instmt_catg` varchar(1) COMMENT '期供种类代码(1-标准期供,2-定制期供,3-多频期供)'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC collate=utf8mb4_unicode_ci COMMENT='贷款账户期供表';

alter table `klnb_instmt` add constraint pk_klnb_instmt primary key (`lgl_pern_code`);

create index klnb_instmt_idx2 on `klnb_instmt` (`loan_due_bill_num`, `rec_ste`, `lgl_pern_code`);

