  `affr_ste_upd_num` varchar(40) COMMENT '事务状态更新唯一编号',
  `loan_due_bill_num` varchar(32) NOT NULL COMMENT '贷款借据号',
  `this_prd_prds` int(10) NOT NULL COMMENT '本期期数',
  `this_prd_actl_acmld_pref_amt` decimal(21,7) DEFAULT 0 COMMENT '本期实际优惠累计金额',
  `this_prd_acmld_pref_amt` decimal(21,2) DEFAULT 0.00 COMMENT '本期优惠累计金额',
  `this_prd_pref_rvrs_amt` decimal(21,2) DEFAULT 0.00 COMMENT '本期优惠反收金额'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC collate=utf8mb4_unicode_ci COMMENT='贷款期供优惠券关联登记簿';

alter table `klnb_instmt_cpns` add constraint pk_klnb_instmt_cpns primary key (`lgl_pern_code`);

create table `klnb_int_caln_attr` (
  `lgl_pern_code` varchar(4) NOT NULL COMMENT '法人代码',
  `mntnc_org` varchar(12) NOT NULL COMMENT '维护机构号',
  `mntnc_tlr` varchar(8) NOT NULL COMMENT '维护柜员号',
  `mntnc_dt` varchar(8) NOT NULL COMMENT '维护日期',
  `mntnc_rung_num` varchar(32) NOT NULL COMMENT '维护流水号',
  `txn_code` varchar(20) NOT NULL COMMENT '核心交易码',
  `tmstp` bigint(19) DEFAULT 0 NOT NULL COMMENT '乐观锁时间戳',
  `rec_ste` varchar(1) NOT NULL COMMENT '记录状态代码(0-正常,1-删除)',
  `affr_ste` varchar(1) DEFAULT 'O' NOT NULL COMMENT '事务状态代码(O-正常,T-在途)',
  `glbl_affr_rung_num` varchar(60) COMMENT '全局事务流水号',
  `affr_ste_upd_num` varchar(40) COMMENT '事务状态更新唯一编号',
  `loan_due_bill_num` varchar(32) NOT NULL COMMENT '贷款借据号',
  `int_caln_prcpl_rule` varchar(1) NOT NULL COMMENT '计息本金规则代码(1-使用放款借据金额计算,2-使用贷款余额计算)',
  `int_caln_min_amt` decimal(21,2) DEFAULT 0 COMMENT '计息最小金额',
  `int_caln_flg` varchar(1) NOT NULL COMMENT '计息标志(Y-是,N-否)',
  `cal_cmpd_int_flg` varchar(1) NOT NULL COMMENT '计复息代码(0-不计息,1-计息,2-计欠息基数,3-计罚息基数)',
  `cmpd_int_caln_flg` varchar(1) NOT NULL COMMENT '复息计息标志(Y-是,N-否)',
  `chk_write_off_int_caln_flg` varchar(1) COMMENT '核销计息标志(Y-是,N-否)',
  `early_strt_int_caln_flg` varchar(1) COMMENT '早起息标志(Y-是,N-否)',
  `dlay_strt_int_caln_flg` varchar(1) COMMENT '晚起息标志(Y-是,N-否)',
  `strt_int_caln_dys` int(10) DEFAULT 0 COMMENT '起息天数',
  `adv_int_collt_way` varchar(1) COMMENT '预收息方式代码(1-不预收息,2-本金扣息,3-总额扣息)',
  `int_amrtn_prd` varchar(8) COMMENT '利息摊销周期',
  `evry_tm_amrtn_way` varchar(1) COMMENT '每次摊销方式代码(1-按比例,2-按期限)',
  `evry_tm_amrtn_pcnt` decimal(6,3) DEFAULT 0 COMMENT '每次摊销比例',
  `next_amrtn_dt` varchar(8) COMMENT '下次摊销日期',
  `last_int_caln_dt` varchar(8) NOT NULL COMMENT '上次计息日期'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC collate=utf8mb4_unicode_ci COMMENT='贷款账户计息属性表';

