  `mntnc_tlr` varchar(8) NOT NULL COMMENT '维护柜员号',
  `mntnc_dt` varchar(8) NOT NULL COMMENT '维护日期',
  `mntnc_rung_num` varchar(32) NOT NULL COMMENT '维护流水号',
  `txn_code` varchar(20) NOT NULL COMMENT '核心交易码',
  `tmstp` bigint(19) DEFAULT 0 NOT NULL COMMENT '乐观锁时间戳',
  `rec_ste` varchar(1) NOT NULL COMMENT '记录状态代码(0-正常,1-删除)',
  `affr_ste` varchar(1) DEFAULT 'O' NOT NULL COMMENT '事务状态代码(O-正常,T-在途)',
  `glbl_affr_rung_num` varchar(60) COMMENT '全局事务流水号',
  `affr_ste_upd_num` varchar(40) COMMENT '事务状态更新唯一编号',
  `loan_due_bill_num` varchar(32) NOT NULL COMMENT '贷款借据号',
  `instmt_gen_way` varchar(1) NOT NULL COMMENT '期供生成方式代码(1-还款规则,2-还款计划书)',
  `instmt_int_tp` varchar(1) NOT NULL COMMENT '期供利息类型代码(1-贷款本金利息,2-本期本金利息)',
  `rpymt_way` varchar(1) NOT NULL COMMENT '还款方式(1-利随本清,2-多次还息一次还本,3-等额本息,4-等额本金,7-等本等息,...)',
  `eqvlt_deal_rule` varchar(1) COMMENT '等额处理规则代码(0-不适用,1-标准+差额,2-标准,3-标准/实际)',
  `rpymt_prd` varchar(8) COMMENT '还款周期',
  `multi_freq_rpymt_flg` varchar(1) COMMENT '多频率还款标志(Y-是,N-否)',
  `prcpl_rpymt_prd` varchar(8) COMMENT '还本周期',
  `ovdue_rpymt_prd` varchar(8) COMMENT '逾期还款周期',
  `pstp_int` decimal(21,2) DEFAULT 0 COMMENT '顺延利息',
  `rpymt_matu` varchar(6) COMMENT '还款期限',
  `rsrvd_amt` decimal(21,2) DEFAULT 0 COMMENT '保留金额',
  `evry_term_rpymt_totl_amt` decimal(21,2) DEFAULT 0 COMMENT '每期还款总额',
  `evry_term_prcpl_rpymt_amt` decimal(21,2) DEFAULT 0 COMMENT '每期还本金额',
  `evry_term_int_rpymt_amt` decimal(21,2) DEFAULT 0 COMMENT '每期还息金额',
  `evry_term_prcpl_rpymt_pcnt` decimal(6,3) DEFAULT 0 COMMENT '每期还本比例',
  `prcpl_in_sects_flg` varchar(1) COMMENT '本金分段代码(0-不适用,1-按本金分段,2-按整笔分段)',
  `cur_prcpl_seg_num` int(10) DEFAULT 0 COMMENT '当前本金段数',
  `custzn_rpymt_plan_flg` varchar(1) COMMENT '定制还本计划标志(Y-是,N-否)',
  `rpymt_plan_change_rule_code` varchar(1) COMMENT '还本计划变更规则代码(2-从后往前,1-从前往后)',
  `totl_prds` int(10) DEFAULT 0 NOT NULL COMMENT '总期数',
  `this_prd_prds` int(10) DEFAULT 0 NOT NULL COMMENT '本期期数',
  `this_prd_sub_prds` int(10) DEFAULT 0 NOT NULL COMMENT '本期子期数',
  `int_caln_totl_prds` int(10) DEFAULT 0 NOT NULL COMMENT '计息总期数',
  `int_caln_prds` int(10) DEFAULT 0 NOT NULL COMMENT '计息期数',
  `int_caln_prcpl` decimal(21,2) DEFAULT 0 NOT NULL COMMENT '计息本金',
  `rpymt_seq_num` varchar(60) NOT NULL COMMENT '还款顺序编号',
  `alw_adv_rpymt` varchar(1) COMMENT '允许提前还款标志(Y-是,N-否)',
  `matu_change_adjust_plan` varchar(1) COMMENT '期限变更调整计划标志(Y-是,N-否)',
  `int_rate_change_adjust_plan` varchar(1) COMMENT '利率变更调整计划标志(Y-是,N-否)',
  `adv_rpymt_adjust_flg` varchar(1) COMMENT '提前还款调整计划标志(Y-是,N-否)',
  `auto_ddc_mny_flg` varchar(1) NOT NULL COMMENT '自动扣款标志(Y-是,N-否)',
  `multi_rpymt_acct_flg` varchar(1) COMMENT '多还款账户标志(Y-是,N-否)',
  `rpymt_acct_num` varchar(40) COMMENT '还款账号',
  `rpymt_sub_acct_serl_num` varchar(8) COMMENT '还款子账户序号',
  `alw_adjust_rpymt_way` varchar(1) COMMENT '允许调整还款方式标志(Y-是,N-否)',
  `first_rpymt_dt_mode` varchar(1) NOT NULL COMMENT '首次还款日确定模式代码(0-指定首次还款日,1-第一个还款日,2-次月还款日)',
  `final_prd_rpymt_way` varchar(1) NOT NULL COMMENT '末期还款方式代码(1-在最后一期进行还款,2-到期日前一期进行还款,3-不足一期算做一期)',
  `defcy_ddc_mny_way` varchar(1) NOT NULL COMMENT '不足额扣款方式代码(1-账户余额全扣款,2-足额扣款不足则不扣)',
  `ovdue_defcy_ddc_mny_way` varchar(1) NOT NULL COMMENT '逾期不足额扣款方式代码(1-账户余额全扣款,2-足额扣款不足则不扣)',
  `hldy_int_pstp_flg` varchar(1) COMMENT '节假日利息顺延标志(Y-是,N-否)',
  `adv_rpymt_min_amt_rule` varchar(1) COMMENT '提前还款最低金额规则代码(1-固定比例,2-固定金额,3-无限制)',
  `adv_rpymt_min_amt_val` decimal(21,2) DEFAULT 0 COMMENT '提前还款最低金额取值',
  `adv_rpymt_max_amt_rule` varchar(1) COMMENT '提前还款最高金额规则代码(1-固定比例,2-固定金额,3-无限制)',
  `adv_rpymt_max_amt_val` decimal(21,2) DEFAULT 0 COMMENT '提前还款最高金额取值',
  `have_grace_prd_flg` varchar(1) NOT NULL COMMENT '有宽限期标志(Y-是,N-否)',
  `int_caln_rule_aft_grace_prd` varchar(1) COMMENT '宽限期后计息规则代码(1-到期日,2-宽限期到期日)',
  `grace_prd_dys` int(10) DEFAULT 0 COMMENT '宽限期天数',
  `grace_prd_int_caln_way` varchar(1) COMMENT '宽限期计息方式代码(1-宽限期不计息,2-按正常利率计算,3-按罚息利率计算)',
  `grace_prd_hldy_rule` varchar(1) COMMENT '宽限期节假日规则代码(P-上一工作日,A-正常处理,N-下一工作日)',
  `last_rpymt_dt` varchar(8) COMMENT '上次还款日',
  `next_rpymt_dt` varchar(8) COMMENT '下次还款日',
  `acmld_ovdue_prds` int(10) DEFAULT 0 COMMENT '累计逾期期数',
  `ctns_ovdue_prds` int(10) DEFAULT 0 COMMENT '连续逾期期数'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC collate=utf8mb4_unicode_ci COMMENT='贷款账户还款属性表';

