  `rpymt_way` varchar(1) NOT NULL COMMENT '还款方式(1-利随本清,2-多次还息一次还本,3-等额本息,4-等额本金,7-等本等息,...)',
  `eqvlt_deal_rule` varchar(1) NOT NULL COMMENT '等额处理规则代码(0-不适用,1-标准+差额,2-标准,3-标准/实际)',
  `rpymt_prd` varchar(8) COMMENT '还款周期',
