  `ovdue_rpymt_prd` varchar(8) NOT NULL COMMENT '逾期还款周期',
  `rpymt_seq_num` varchar(60) NOT NULL COMMENT '还款顺序编号',
  `prcpl_in_sects_flg` varchar(1) NOT NULL COMMENT '本金分段代码(0-不适用,1-按本金分段,2-按整笔分段)',
  `alw_adjust_rpymt_way` varchar(1) COMMENT '允许调整还款方式标志(Y-是,N-否)',
  `first_rpymt_dt_mode` varchar(1) NOT NULL COMMENT '首次还款日确定模式代码(0-指定首次还款日,1-第一个还款日,2-次月还款日)',
  `final_prd_rpymt_way` varchar(1) NOT NULL COMMENT '末期还款方式代码(1-在最后一期进行还款,2-到期日前一期进行还款,3-不足一期算做一期)',
  `auto_ddc_mny_flg` varchar(1) COMMENT '自动扣款标志(Y-是,N-否)',
  `multi_rpymt_acct_flg` varchar(1) COMMENT '多还款账户标志(Y-是,N-否)',
  `defcy_ddc_mny_way` varchar(1) NOT NULL COMMENT '不足额扣款方式代码(1-账户余额全扣款,2-足额扣款不足则不扣)',
  `ovdue_defcy_ddc_mny_way` varchar(1) NOT NULL COMMENT '逾期不足额扣款方式代码(1-账户余额全扣款,2-足额扣款不足则不扣)',
  `adv_rpymt_min_amt_rule` varchar(1) COMMENT '提前还款最低金额规则代码(1-固定比例,2-固定金额,3-无限制)',
  `adv_rpymt_min_amt_val` decimal(21,2) DEFAULT 0 COMMENT '提前还款最低金额取值',
  `adv_rpymt_max_amt_rule` varchar(1) COMMENT '提前还款最高金额规则代码(1-固定比例,2-固定金额,3-无限制)',
  `adv_rpymt_max_amt_val` decimal(21,2) DEFAULT 0 COMMENT '提前还款最高金额取值',
  `adv_rpymt_adjust_flg` varchar(1) COMMENT '提前还款调整计划标志(Y-是,N-否)',
  `matu_change_adjust_plan` varchar(1) COMMENT '期限变更调整计划标志(Y-是,N-否)',
  `int_rate_change_adjust_plan` varchar(1) COMMENT '利率变更调整计划标志(Y-是,N-否)',
  `have_grace_prd_flg` varchar(1) NOT NULL COMMENT '有宽限期标志(Y-是,N-否)',
  `grace_prd_dys` int(10) DEFAULT 0 COMMENT '宽限期天数',
  `grace_prd_int_caln_way` varchar(1) COMMENT '宽限期计息方式代码(1-宽限期不计息,2-按正常利率计算,3-按罚息利率计算)',
  `int_caln_rule_aft_grace_prd` varchar(1) COMMENT '宽限期后计息规则代码(1-到期日,2-宽限期到期日)',
  `grace_prd_hldy_rule` varchar(1) COMMENT '宽限期节假日规则代码(P-上一工作日,A-正常处理,N-下一工作日)',
  `rpymt_prty` bigint(32) COMMENT '还款优先级'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC collate=utf8mb4_unicode_ci COMMENT='贷款产品还款属性表';

