  `rec_ste` varchar(1) NOT NULL COMMENT '记录状态代码(0-正常,1-删除)',
  `affr_ste` varchar(1) DEFAULT 'O' NOT NULL COMMENT '事务状态代码(O-正常,T-在途)',
  `glbl_affr_rung_num` varchar(60) COMMENT '全局事务流水号',
  `affr_ste_upd_num` varchar(40) COMMENT '事务状态更新唯一编号',
  `acct_num` varchar(40) NOT NULL COMMENT '账号',
  `acct_nm` varchar(750) NOT NULL COMMENT '账户名称',
  `intrl_acct_busi_catg` varchar(2) NOT NULL COMMENT '内部户分类代码(01-存放同业活期,02-存放同业定期,03-暂收暂付,04-待销账,05-表外账,...)',
  `acct_blgd_org` varchar(12) NOT NULL COMMENT '账户归属机构号',
  `ccy_code_num` varchar(3) NOT NULL COMMENT '币种(AUD-澳大利亚元,CAD-加元,CHF-瑞士法郎,DKK-丹麦克朗,EUR-欧元,...)',
  `busi_code` varchar(60) NOT NULL COMMENT '业务编码',
  `acct_num_serl_num` varchar(8) NOT NULL COMMENT '账号序号',
  `bal_drcn` varchar(1) NOT NULL COMMENT '余额方向代码(D-借方,C-贷方)',
  `acct_bal` decimal(21,2) DEFAULT 0 NOT NULL COMMENT '账户余额',
  `acmld_acmlv_num` decimal(21,2) DEFAULT 0 NOT NULL COMMENT '累计积数',
  `bal_lately_upd_dt` varchar(8) COMMENT '余额最近更新日期',
  `last_dy_acct_bal` decimal(21,2) DEFAULT 0 NOT NULL COMMENT '上日账户余额',
  `last_dy_bal_drcn` varchar(1) COMMENT '上日余额方向代码(D-借方,C-贷方)',
  `loan_matu` varchar(6) NOT NULL COMMENT '贷款期限',
  `strt_int_caln_dt` varchar(8) NOT NULL COMMENT '起息日期',
  `matu_dt` varchar(8) NOT NULL COMMENT '到期日期',
  `int_caln_rule` varchar(2) COMMENT '计息规则代码(00-标准/标准(30/360),01-对月对日(30/365,366),02-标准/365(30/365),10-实际/标准(31/360),11-实际/实际(31/365,366),...)',
  `acrl_flg` varchar(1) NOT NULL COMMENT '计提标志(Y-是,N-否)',
  `exec_int_rate` decimal(12,7) COMMENT '执行利率',
  `acrl_int` decimal(21,7) DEFAULT 0 NOT NULL COMMENT '计提利息',
  `acmld_acrl_int` decimal(21,7) DEFAULT 0 NOT NULL COMMENT '累计计提利息',
  `acmld_int_pymt_amt` decimal(21,2) DEFAULT 0 NOT NULL COMMENT '累计付息金额',
  `last_acrl_dt` varchar(8) COMMENT '上次计提日期',
  `last_int_pymt_dt` varchar(8) COMMENT '上次付息日期',
  `ctr_num` varchar(30) COMMENT '合同号',
  `itrbnk_bank_num` varchar(12) COMMENT '同业行号',
  `itrbnk_bank_nm` varchar(200) COMMENT '同业行名',
  `itrbnk_acct_num` varchar(40) COMMENT '同业账号',
  `itrbnk_acct_nm` varchar(750) COMMENT '同业户名',
  `open_acct_sys` varchar(6) NOT NULL COMMENT '开户系统代码',
  `open_acct_chnl` varchar(7) NOT NULL COMMENT '开户渠道代码',
  `open_acct_org` varchar(12) NOT NULL COMMENT '开户机构号',
  `open_acct_dt` varchar(8) NOT NULL COMMENT '开户日期',
  `open_acct_tlr_num` varchar(8) NOT NULL COMMENT '开户柜员号',
  `open_acct_rung_num` varchar(32) NOT NULL COMMENT '开户流水号',
  `cncl_acct_org` varchar(12) COMMENT '销户机构号',
  `cncl_acct_dt` varchar(8) COMMENT '销户日期',
  `cncl_acct_tlr` varchar(8) COMMENT '销户柜员号',
  `cncl_acct_rung_num` varchar(32) COMMENT '销户流水号',
  `intrl_acct_ste` varchar(1) NOT NULL COMMENT '内部户账户状态代码(N-未生效,0-关闭,1-正常,2-销户,3-重启,...)'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC collate=utf8mb4_unicode_ci COMMENT='付息同业分户表';

